import ghidra.app.script.GhidraScript; import ghidra.program.model.listing.*; import ghidra.program.model.address.*; import java.io.*;
public class VerifyAsm extends GhidraScript { public void run() throws Exception { String out=getScriptArgs()[0]; try(PrintWriter pw=new PrintWriter(out)){ for(long[] r: new long[][]{{0x13d160,0x13d178},{0x144e44,0x144e5c},{0x3d6d58,0x3d6e08},{0x3d6e08,0x3d6e28},{0x3d6e28,0x3d6e48},{0x3d6eb0,0x3d6f50},{0x3d6f50,0x3d6f84}}){ Address a=toAddr(r[0]); clearListing(a,toAddr(r[1])); disassemble(a); while(a.getOffset()<r[1]){ Instruction in=getInstructionAt(a); pw.printf("%s %s\n",a,in); a=a.add(in!=null?in.getLength():4);} pw.println(); } } } }
